// Builds the designer prototype: node build-designer.js   (run from anywhere)
// 1. Slices the pure science model out of ../Adapt-Lab.html into _model.gen.js (window.AdaptModel), unchanged.
// 2. Inlines designer.css and every local <script src> of designer.src.html into Adapt-Lab-Designer-Prototype.html.
//    Files that do not exist yet (extra body plans, biomes, cost, combos) are skipped, so the build never breaks.
const fs=require('fs'),path=require('path');const d=__dirname;
const old=fs.readFileSync(path.join(d,'..','Adapt-Lab.html'),'utf8');
function between(a,b,incl){const i=old.indexOf(a);if(i<0)throw new Error('marker not found: '+a);const j=old.indexOf(b,i+a.length);if(j<0)throw new Error('marker not found: '+b);return old.slice(i,incl?old.indexOf('\n',j)+1:j)}
const parts=[
  between('const clamp=','const RM='),                                        // clamp, rng, hashStr, css
  between('/* ================= vocabulary','function v(term,text)',true),    // VOCAB and v()
  between('/* ================= data =================','/* ================= notes'), // data, models, hazards, classification
  between('function isSwimmer(','\n',false)+'\n',
  between('function canHunt(','return v<.03?0:v}',true)
];
const model='/* GENERATED by build-designer.js from Adapt-Lab.html. Do not edit: change the sim, then rebuild. */\n(function(root){\n"use strict";\nconst $=()=>null;\n'+parts.join('\n')+
  '\nroot.AdaptModel={VOCAB,PAL,BIOMES,A_SECTIONS,A_SLIDERS,DEF_A,PRESETS,PRED_BANK,scoresFor,animalScores,yearSurvival,lethalOf,seasonHaz,classify,realChecks,moveAbility,getB,clamp};\n})(typeof window!=="undefined"?window:globalThis);\n';
fs.writeFileSync(path.join(d,'_model.gen.js'),model);
const srcPath=path.join(d,'designer.src.html');
if(fs.existsSync(srcPath)){
  const safe=s=>s.replace(/<\/script/g,'<\\/script');
  let html=fs.readFileSync(srcPath,'utf8');const used=[],skipped=[];
  html=html.replace(/<link rel="stylesheet" href="([^"]+)">/g,(m,f)=>{const p=path.join(d,f);return fs.existsSync(p)?'<style>\n'+fs.readFileSync(p,'utf8')+'\n</style>':''});
  html=html.replace(/<script src="([^"]+)"><\/script>/g,(m,f)=>{const p=path.join(d,f);if(!fs.existsSync(p)){skipped.push(f);return''}used.push(f);return'<script>\n'+safe(fs.readFileSync(p,'utf8'))+'\n</script>'});
  fs.writeFileSync(path.join(d,'Adapt-Lab-Designer-Prototype.html'),html);
  console.log('built Adapt-Lab-Designer-Prototype.html',html.length,'bytes · included:',used.join(', '),'· not there yet:',skipped.join(', ')||'none');
}else console.log('wrote _model.gen.js',model.length,'bytes');
